//===- mac_sparse.cc --------------------------------------------*- C++ -*-===//
//
// probe capture kernel for sparse MAC config mode (1, 2, 2) `2x16_16x8`
// (GENERATED by tools/gen_mac_sparse.py). Per tile and signedness flavour it builds the sparse B operand with update() from a stored-data block and a mask block,
// then runs mul.
// Chunk layout: 3 operand blocks of T tiles (A0 D0 M0).
//
//===----------------------------------------------------------------------===//

#include <stdint.h>

// Peano builds see no Chess-side define; the stream/ADF half of aie_api is not needed.
#ifndef __AIE_API_AIE_ADF_HPP__
#define __AIE_API_AIE_ADF_HPP__
#endif
#include <aie_api/aie.hpp>

#define T 32
#define OUT_WORDS_PER_TILE 128

#define STORE(r, dst) \
  do { aie::accum<acc64, 16> w(r); aie::store_v((dst), w.to_vector<int32>(0)); aie::store_v((dst) + 16, w.to_vector<int32>(32)); } while (0)

extern "C" {

void mac_sparse(uint8_t *restrict in, int32_t *restrict out) {
  uint8_t *in0 = in + 0;
  uint8_t *in1 = in + 0 + T * 64;
  uint8_t *in2 = in + 0 + T * 64 + T * 64;
  // Read the 64-bit lanes as two 32-bit halves: srs by 0 and by 32 with no saturation.
  aie::set_saturation(aie::saturation_mode::none);
  aie::set_rounding(aie::rounding_mode::floor);
  event0();
  for (int n = 0; n < T; n++) {
    int32_t *o = out + n * OUT_WORDS_PER_TILE;
    { // ss
      v32int16 a0 = *(v32int16 *)(in0 + n * 64);
      v64int8 d0 = *(v64int8 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v128int8_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v16acc64 r0 = mul_2x16_16x8(a0, b0);
      STORE(r0, o + 0);
    }
    { // su
      v32int16 a0 = *(v32int16 *)(in0 + n * 64);
      v64uint8 d0 = *(v64uint8 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v128uint8_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v16acc64 r0 = mul_2x16_16x8(a0, b0);
      STORE(r0, o + 32);
    }
    { // us
      v32uint16 a0 = *(v32uint16 *)(in0 + n * 64);
      v64int8 d0 = *(v64int8 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v128int8_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v16acc64 r0 = mul_2x16_16x8(a0, b0);
      STORE(r0, o + 64);
    }
    { // uu
      v32uint16 a0 = *(v32uint16 *)(in0 + n * 64);
      v64uint8 d0 = *(v64uint8 *)(in1 + n * 64);
      sparsity_t m0 = *(sparsity_t *)(in2 + n * 16);
      v128uint8_sparse b0;
      b0 = update(b0, d0);
      b0 = update(b0, m0);
      v16acc64 r0 = mul_2x16_16x8(a0, b0);
      STORE(r0, o + 96);
    }
  }
  event1();
}

} // extern "C"
